 function updateWorkflow(){if(!workflow)return;const text=$('[data-aigc-text]')?.value||'',hasText=!!text.trim();let valid=false;try{validateAigcText(text,cap);valid=true;}catch{}const hasReport=!!item?.fullyCompleted&&(!item.reportAvailable||!!resultText),known=workflowText??(resultText||null),newDraft=!!item&&!['running'].includes(item.status)&&hasText&&(known===null||text!==known);const phase=blocked?'blocked':importing?'importing':item?.status==='running'?'running':intent?(busy?'submitting':'recovering'):newDraft?'review':item?.status==='failed'?'failed':item?.fullyCompleted?(hasReport?'complete':'report_pending'):item?.status==='completed'?'report_pending':$('[data-detection-progress]')&&busy?'submitting':hasText?'review':'prepare';workflow.update({phase,hasText,valid,hasTask:!!(item||intent||$('[data-detection-progress]'))&&!newDraft,hasReport,newDraft});}
