 $('[data-aigc-title]').oninput=()=>{updateControls();};$('[data-aigc-text]').oninput=()=>{countInput();};$('[data-aigc-start]').onclick=()=>void command(submit);$('[data-aigc-refresh]').onclick=()=>void command(()=>read(item.id));$('[data-aigc-retry]').onclick=()=>void command(retry);
 const fileInput=$('[data-aigc-file]'),zone=$('[data-aigc-upload]');fileInput.onchange=()=>{const file=fileInput.files?.[0];fileInput.value='';if(file)void importFile(file);};
